133	    public void setCustomerCode(String customerCode) {
134	        this.customerCode = customerCode;
135	    }
136	
137	    public String getMembershipNumber() {
138	        return this.membershipNumber;
139	    }
140	
141	    public void setMembershipNumber(String membershipNumber) {
142	        this.membershipNumber = membershipNumber;
143	    }
144	
145	    public String getHouseholdId() {
146	        return this.householdId;
147	    }
148	
149	    public void setHouseholdId(String householdId) {
150	        this.householdId = householdId;
151	    }
152	
153	    public Integer getNamesakeCount() {
154	        return this.namesakeCount;
155	    }
156	
157	    public void setNamesakeCount(Integer namesakeCount) {
158	        this.namesakeCount = namesakeCount;
159	    }
160	
161	    public Integer getHouseholdSize() {
162	        return this.householdSize;
163	    }
164	
165	    public void setHouseholdSize(Integer householdSize) {
166	        this.householdSize = householdSize;
167	    }
168	
169	    public Integer getMembershipLevel() {
170	        return this.membershipLevel;
171	    }
172	
173	    public void setMembershipLevel(Integer membershipLevel) {
174	        this.membershipLevel = membershipLevel;
175	    }
176	
177	    /**
178	     * The owner's locality: the canonical region derived from the postcode range via
179	     * {@link RegionPostcodes}, falling back to the city via the fixed {@link CityRegion} table when
180	     * the postcode is absent or in no known range. This disambiguates cities that share a name.
181	     * Yields {@code "UNKNOWN"} when neither postcode nor city resolves to a region.
182	     */
183	    @Transient
184	    public String getLocality() {
185	        String byPostcode = RegionPostcodes.regionOf(this.postcode);
186	        return byPostcode != null ? byPostcode : CityRegion.of(this.city);
187	    }
188	
189	    /**
190	     * The owner's check digit: the single Luhn check digit computed over the digits of the
191	     * {@code customerCode}, guarding against transcription errors of the code.
192	     */
193	    @Transient
194	    public int getCheckDigit() {
195	        return Luhn.checkDigit(this.customerCode);
196	    }
197	
198	    /**
199	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
200	     * present, otherwise {@code "PHONE"}.
201	     */
202	    @Transient
203	    public String getContactPreference() {
204	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
205	    }
206	
207	    /**
208	     * The owner's identity key: the single derived value all duplicate detection is expressed
209	     * through, formed as {@code <normalizedTelephone>|<email or empty>|<householdId or empty>}.
210	     * Two owners are duplicates only when their whole identity keys are equal, so members of one
211	     * household (same {@code householdId}) with different telephones have different keys.
212	     */
213	    @Transient
214	    public String getIdentityKey() {
215	        return blankToEmpty(this.telephone) + '|' + blankToEmpty(this.email) + '|' + blankToEmpty(this.householdId);
216	    }
217	
218	    private static String blankToEmpty(String value) {
219	        return (value == null) ? "" : value;
220	    }
221	
222	    protected Set<Pet> getPetsInternal() {
223	        if (this.pets == null) {
224	            this.pets = new HashSet<>();
225	        }
226	        return this.pets;
227	    }
228	
229	    protected void setPetsInternal(Set<Pet> pets) {
230	        this.pets = pets;
231	    }
232	
233	    public List<Pet> getPets() {
234	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
235	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
236	        return Collections.unmodifiableList(sortedPets);
237	    }
238	
239	    public void setPets(List<Pet> pets) {
240	        this.pets = new HashSet<>(pets);
241	    }
242	
243	    public void addPet(Pet pet) {
244	        getPetsInternal().add(pet);
245	        pet.setOwner(this);
246	    }
247	
248	    /**
249	     * Return the Pet with the given name, or null if none found for this Owner.
250	     *
251	     * @param name to test
252	     * @return true if pet name is already in use
253	     */
254	    public Pet getPet(String name) {
255	        return getPet(name, false);
256	    }
257	
258	    /**
259	     * Return the Pet with the given name, or null if none found for this Owner.
260	     *
261	     * @param name to test
262	     * @return true if pet name is already in use
263	     */
264	    public Pet getPet(String name, boolean ignoreNew) {
265	        name = name.toLowerCase();
266	        for (Pet pet : getPetsInternal()) {
267	            if (!ignoreNew || !pet.isNew()) {
268	                String compName = pet.getName();
269	                compName = compName.toLowerCase();
270	                if (compName.equals(name)) {
271	                    return pet;
272	                }
273	            }
274	        }
275	        return null;
276	    }
277	
278	    public Pet getPet(Integer petId) {
279	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
280	    }
281	
282	    @Override
283	    public String toString() {
284	        return new ToStringCreator(this)
285	
286	            .append("id", this.getId())
287	            .append("new", this.isNew())
288	            .append("lastName", this.getLastName())
289	            .append("firstName", this.getFirstName())
290	            .append("address", this.address)
291	            .append("city", this.city)
292	            .append("telephone", this.telephone)
293	            .toString();
294	    }
295	}
