3	import java.util.regex.Pattern;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.CityRegion;
7	import org.springframework.samples.petclinic.model.RegionPostcodes;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
10	import org.springframework.util.StringUtils;
11	
12	/**
13	 * Validates the optional postcode of an owner request. When present it must be a 4-digit value that
14	 * is valid for the region derived from the owner's city ({@link CityRegion} then
15	 * {@link RegionPostcodes}): a city with no known region accepts any 4-digit postcode. An absent (or
16	 * blank) postcode is left untouched, since postcode is optional. Rejects a present-but-invalid
17	 * postcode with 400.
18	 */
19	public class ValidateOwnerPostcode {
20	
21	    private static final Pattern FOUR_DIGITS = Pattern.compile("[0-9]{4}");
22	
23	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
24	        String postcode = request.getPostcode();
25	        if (!StringUtils.hasText(postcode)) {
26	            return;
27	        }
28	        if (!FOUR_DIGITS.matcher(postcode).matches()
29	                || !RegionPostcodes.isInRange(CityRegion.of(request.getCity()), Integer.parseInt(postcode))) {
30	            throw new InvalidPostcodeException(postcode, request.getCity());
31	        }
32	    }
33	}
