1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.util.StringUtils;
6	
7	/**
8	 * Assigns a newly built owner its numeric {@code membershipLevel}. Starting from 1, the level
9	 * gains a point when the owner has an email address and another when it had no namesakes at
10	 * creation ({@link Owner#getNamesakeCount()} is 0), capped at 3. Level 4 is reserved for tenure
11	 * and so is never assigned here. Runs after {@link CountNamesakes} so the namesake count is set.
12	 */
13	public class AssignMembershipLevel {
14	
15	    /** The highest membership level assignable on creation; level 4 is reserved for tenure. */
16	    private static final int MAX_LEVEL_ON_CREATION = 3;
17	
18	    public void service(@Val Owner owner) {
19	        int level = 1;
20	        if (StringUtils.hasText(owner.getEmail())) {
21	            level++;
22	        }
23	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
24	            level++;
25	        }
26	        owner.setMembershipLevel(Math.min(level, MAX_LEVEL_ON_CREATION));
27	    }
28	}
