7	/**
8	 * Records on the newly built owner how many existing owners already share its first and last name,
9	 * matched case-insensitively. Runs before the owner is saved, so the count reflects the state of the
10	 * data store immediately before this create.
11	 */
12	public class CountNamesakes {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        long count = ownerRepository.findByLastName(owner.getLastName()).stream()
16	            .filter(existing -> existing.getLastName().equalsIgnoreCase(owner.getLastName())
17	                && existing.getFirstName().equalsIgnoreCase(owner.getFirstName()))
18	            .count();
19	        owner.setNamesakeCount((int) count);
20	    }
21	}
