43	        if (raw == null) {
44	            return null;
45	        }
46	        String cleaned = SEPARATORS.matcher(raw).replaceAll("");
47	        String digits;
48	        if (cleaned.startsWith("+")) {
49	            digits = cleaned.substring(1);
50	        }
51	        else {
52	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
53	            digits = DEFAULT_COUNTRY_CODE + national;
54	        }
55	        if (!E164_DIGITS.matcher(digits).matches() || !hasValidNationalLength(digits)) {
56	            return null;
57	        }
58	        return "+" + digits;
59	    }
60	
61	    /**
