71	        String countryCode = null;
72	        for (String code : NATIONAL_LENGTHS.keySet()) {
73	            if (digits.startsWith(code) && (countryCode == null || code.length() > countryCode.length())) {
74	                countryCode = code;
75	            }
76	        }
77	        if (countryCode == null) {
78	            return true;
79	        }
80	        return digits.length() - countryCode.length() == NATIONAL_LENGTHS.get(countryCode);
